mapper.select:
select lauar.id, lauar.user_id, lauar.award_id, lauar.type, lauar.award, lauar.create_user_id, lauar.update_user_id, lauar.create_time, lauar.update_time, usess.nickname as userName, awards.name as awardName, awards.equity_name from la_activity_user_award_record lauar join la_user usess on lauar.user_id = usess.id join la_activity_award awards on lauar.award_id = awards.id
and lauar.is_delete = 0
and lauar.user_id = #{param.userId}
and lauar.award_id = #{param.awardId}
and lauar.type = #{param.type}
and lauar.award like concat('%',#{param.award},'%')
and lauar.create_user_id = #{param.createUserId}
and lauar.update_user_id = #{param.updateUserId}
order by lauar.id desc
